insert into public.support_ai_knowledge (topic, content, active, source, verified_at) values
('support_entrypoint','Wavo support is the dedicated /support page. The old human support DM account has been retired. Do not tell users to message a support account.',true,'Vercel production + migration retire_legacy_support_chat',now()),
('account_signin','The current Wavo sign-in form asks for a username and password. Internally Wavo maps the username to a synthetic @wavo.app auth email, but users should be told to sign in with their username, not an email address.',true,'github:src/App.jsx AuthScreen',now()),
('account_signup','The current signup form asks for a username and password. Passwords must be at least 6 characters in the current UI. After account creation the user logs in with the username and password.',true,'github:src/App.jsx AuthScreen',now()),
('password_reset','There is no self-serve password reset flow in the current Wavo UI. Do not invent a Forgot password menu or email-reset flow.',true,'github:src/App.jsx AuthScreen',now()),
('username_change','Username changes are available in the You tab, inside the Identity card under Username. Usernames are 3-24 lowercase letters, numbers or underscores, must be unique, and can be changed once every 7 days. The sign-in username changes at the same time.',true,'github:src/UsernameSettings.jsx + live change-username function',now()),
('profile_identity','The You tab contains an Identity card. Users can edit Status and a Bio of up to 180 characters, and can change their username using the Username control in that card.',true,'github:src/App.jsx ProfileScreen + UsernameSettings.jsx',now()),
('privacy_settings','Wavo privacy settings include Show online status, Read receipts, Allow friend requests, who can message the user, and a default location-sharing mode. Live allowed message scopes are friends, anyone, or nobody; location defaults are off, approximate, or precise.',true,'supabase:privacy_settings and profiles schema',now()),
('friends','Wavo has username search, friend requests, accepted friends and blocking. Incoming friend requests can be accepted from the app.',true,'github:src/wavoData.js + supabase friend_requests/blocks',now()),
('direct_messages','Direct messages are one-to-one conversations between users. The live message model supports text plus message metadata for images/files, voice-note duration, replies, forwarded state, read state, edits and deletion timestamps.',true,'supabase:messages schema + github:src/App.jsx',now()),
('message_read_receipts','DM messages have is_read and read_at fields. Read-receipt visibility is controlled by the users Read receipts privacy setting.',true,'supabase:messages + privacy_settings schema',now()),
('message_delete','Wavo has DM and Space message-delete actions. Do not claim that deleting a message deletes an entire conversation unless the UI explicitly says so.',true,'github:src/uxData.js + App.jsx imports',now()),
('message_pins','Chats can be pinned for a user. Wavo stores per-user chat pins and also has message-pin data.',true,'github:src/uxData.js + supabase chat_pins/message_pins',now()),
('nicknames','Users can assign personal nicknames to chat contacts. Nicknames are stored per user and do not rename the other persons account.',true,'github:src/uxData.js + supabase:nicknames',now()),
('scheduled_messages','Wavo supports scheduling direct messages for a future send time. The current scheduling helper is for DMs; do not claim Space messages can be scheduled unless that is added later.',true,'github:src/uxData.js scheduleDmMessage + supabase:scheduled_messages',now()),
('voice_notes','Wavo supports voice notes in messaging. Message records can store voice-note duration in milliseconds.',true,'supabase voice_notes migration + messages.duration_ms',now()),
('spaces','Wavo Spaces are group conversations. A Space can have a name, description, emoji and accent, and members have roles including owner/member.',true,'github:src/wavoData.js + supabase:groups/group_members',now()),
('space_messages','Space messages are stored separately from DMs and are loaded in chronological order. The current normal send flow inserts text messages into the group conversation.',true,'github:src/wavoData.js getSpaceMessages/sendSpaceMessage',now()),
('waves','In the live implementation, newly created Waves default to expiring after 24 hours. Waves can target friends, a group, or selected recipient IDs, can contain text/media data, and support reactions.',true,'supabase:waves schema + github:createWave',now()),
('posts','Wavo also has persistent Posts separate from Waves. Posts support friend/selected audiences, reactions, and authors can delete their own posts.',true,'supabase:posts/post_audience/post_reactions + github:src/App.jsx',now()),
('plans','Plans can be created for a Space with a title, start time, optional location and notes. RSVP choices shown in the current UI are Going, Maybe and Can''t.',true,'github:src/wavoData.js + App.jsx PlanCard',now()),
('plan_location','Plans can store place details. Wavo also supports temporary location sharing tied to a plan; the current helper defaults to 60 minutes and roughly 250 m precision when no other values are supplied.',true,'github:src/wavoData.js sharePlanLocation + supabase:plans',now()),
('polls','Wavo polls have a question and options and can belong to a Space or plan. Polls can be single-choice or allow multiple choices depending on the poll configuration.',true,'supabase:polls/poll_options/poll_votes + github:wavoData.js',now()),
('activities','Wavo has group Activities stored in the live backend. Active activities can be created with a type, title and state/items.',true,'github:src/wavoData.js + supabase:activities',now()),
('calls','Wavo has one-to-one call sessions with caller, callee, mode and lifecycle status. A ringing call currently expires after about 45 seconds in the live database. Voice/video calling and iOS CallKit/VoIP-push support exist in the current codebase.',true,'supabase:call_sessions + github iOS CallKit/push migrations',now()),
('call_timeout','A ringing one-to-one call has an expires_at timestamp defaulting to 45 seconds after creation. Expired calls should not reconnect later. If a stale call appears after timeout, treat that as a Wavo bug rather than telling the user it is expected.',true,'supabase:call_sessions schema + harden_call_lifecycle migrations',now()),
('notifications','Wavo supports web push and native iOS push. Users should first check OS/browser notification permission and that they are signed into the intended Wavo account. TestFlight/App Store builds use production APNs.',true,'supabase:push_subscriptions + github:docs/PUSH-SETUP.md',now()),
('ios_push','For the current iOS app, push registration is tied to the signed-in account and the app has logic to claim/release APNs device tokens across login/logout. TestFlight uses production APNs rather than sandbox APNs.',true,'supabase push migrations + github:docs/PUSH-SETUP.md',now()),
('streaks','Wavo has friendship streak/stat data. Streak logic was migrated to count message sends and use the users timezone. Do not guess a streak value without account data.',true,'supabase migrations cosmetics_stats_streaks/fix_streak_timezone',now()),
('themes_cosmetics','Wavo supports themes, badges and name styles. Profiles store equipped theme, badge and name style, and there is a user_cosmetics inventory. Some cosmetics can be Premium/tier-aware.',true,'supabase:profiles/cosmetics/user_cosmetics + migrations',now()),
('premium','Wavo has Free/Premium account state in the live profile data and website checkout is handled through Stripe. Do not quote a price unless it is present in the current UI or supplied by the user because pricing can change.',true,'supabase:profiles + github:api/checkout.js',now()),
('spotify','Wavo contains Spotify presence support with Spotify connection/OAuth backend data. Do not claim Spotify is connected for a specific user unless account data confirms it.',true,'github:SpotifyPresenceCoordinator + supabase:spotify_connections',now()),
('offline_drafts','The app contains local caching, drafts and an outbox/retry layer for offline use. If a send appears stuck, reconnecting and reopening Wavo can allow queued work to retry, but do not claim a message reached the server until it appears in the conversation.',true,'github:src/offline.js + App.jsx imports',now()),
('blocking_reporting','Blocking and reporting are separate safety actions. Wavo has a blocks table and flags/reporting data. Do not say a report automatically blocks someone or vice versa.',true,'supabase:blocks/flags + app-store-safety migration',now()),
('account_delete','Wavo documentation and privacy/terms pages describe self-service account deletion under Settings > Account. Deletion is intended to permanently remove the account data; warn that it is destructive. If the current UI does not show that control, do not invent a different path.',true,'github:public/privacy.html + terms.html + support.html',now()),
('platforms','The current Wavo project ships as a web app and an iOS Capacitor app. Production web is deployed on Vercel at www.wavo.lol, with wavo.lol redirecting to www.wavo.lol.',true,'Vercel production project + github README/Capacitor',now()),
('support_accuracy','Never invent menu paths, settings, prices, account state or feature behavior. Prefer the live implementation facts in this knowledge base. If two sources conflict, prefer the current production/live database and current source code over old docs, and say when something is uncertain.',true,'support policy verified 2026-09-07',now()),
('bug_reports','For a Wavo bug report, collect the exact screen/action, expected result, actual result, platform (web or iOS), device/OS/browser when known, and whether it reproduces. Never claim the bug is fixed unless the current deployed code or backend confirms it.',true,'support policy + Vercel/Supabase/GitHub debugging workflow',now()),
('product','Wavo is a web and iOS social app built around direct messages, Spaces/group chats, Waves, persistent Posts, Plans, Polls, Activities, games, voice/video calls, notifications, profiles, privacy controls, themes/cosmetics and Premium. Support is at /support.',true,'github current app + supabase live schema + Vercel production',now())
